import {BUILDING_MATERIALS,SURFACE_NAMES,exposedSurface,paintBuildingSurface} from './building-materials.js?v=education-service-maps-1';
import {towerToBlocks,paintBuildingBlock} from './building-blocks.js?v=education-service-maps-1';
export function mountBuildingBlockEditor(root,{get,set}){
 root.innerHTML=`<label>Construction method<select id="blockMode"><option value="tower">Tower parameters</option><option value="blocks">Paint a block layout</option></select></label><section id="blockWorkspace" hidden><p>Paint a height onto the footprint. Use 0 to erase. Drag across squares, or use arrow keys and Enter/Space. The footprint stays north-up while the preview rotates. Heights are floors.</p><div class="block-editor-controls"><label>Editing tool<select id="blockTool"><option value="height">Height brush</option><option value="paint">Surface paintbrush</option><option value="fill">Fill connected surfaces</option></select></label><label>Surface<select id="blockSide">${SURFACE_NAMES.map((name,i)=>`<option value="${i}">${name}</option>`).join('')}</select></label><label>Material<select id="blockMaterial">${BUILDING_MATERIALS.map((name,i)=>`<option value="${i}">${name}</option>`).join('')}</select></label><label>Height brush (0–24)<input id="blockBrush" type="number" min="0" max="24" step="1" value="8"></label><button id="blockUndo">Undo layout edit</button><button id="blockFromTower">Use tower footprint</button><button id="blockClear">Clear footprint</button></div><div id="blockGrid" role="grid" aria-label="Building footprint, north at top" aria-rowcount="10" aria-colcount="10">${Array.from({length:10},(_,y)=>`<div role="row">${Array.from({length:10},(_,x)=>`<button type="button" role="gridcell" data-block-index="${y*10+x}" tabindex="${x===0&&y===0?0:-1}"></button>`).join('')}</div>`).join('')}</div><p>Surface tools paint the selected side of each column. Fill joins touching surfaces with the same height and material; walls stay on one plane. Hidden walls cannot be painted.</p><p id="blockStatus" role="status"></p></section>`;
 const $=id=>root.querySelector('#'+id),grid=$('blockGrid'),cells=[...grid.querySelectorAll('[data-block-index]')],history=[];let memory=null,active=0,stroke=null,strokeSaved=false;
 const isBlocks=()=>Array.isArray(get().blocks),snapshot=()=>({blocks:[...get().blocks],...(get().materials?{materials:[...get().materials]}:{})});
 function refresh(){const blocks=get().blocks; $('blockMode').value=blocks?'blocks':'tower';$('blockWorkspace').hidden=!blocks;for(const id of ['designFloors','designWidth','designDepth','designRoof'])document.getElementById(id).disabled=!!blocks;$('blockUndo').disabled=!history.length;const painting=$('blockTool').value!=='height',side=Number($('blockSide').value);$('blockBrush').disabled=painting;$('blockSide').disabled=!painting;$('blockMaterial').disabled=!painting;if(!blocks)return;cells.forEach((cell,i)=>{const h=blocks[i],material=get().materials?.[i*5+side]||0,exposed=exposedSurface(blocks,i,side);cell.textContent=painting?(exposed?['F','B','S','G','T'][material]:'·'):(h||'·');cell.setAttribute('aria-label',`Column ${i%10+1}, row ${Math.floor(i/10)+1}: ${h} floors${painting?`, ${SURFACE_NAMES[side]}: ${exposed?BUILDING_MATERIALS[material]:'not exposed'}`:''}`);cell.tabIndex=i===active?0:-1;cell.style.background=painting?(exposed?['#b6c4bd','#aa6750','#d4c5aa','#3c6b79','#7a5960'][material]:'#eef1ef'):`hsl(172 20% ${94-h*1.7}%)`;cell.style.color=painting?(exposed&&[1,3,4].includes(material)?'#fff':'#17382f'):(h>14?'#fff':'#17382f');});$('blockStatus').textContent=blocks.some(h=>h)?`${blocks.filter(h=>h).length} occupied squares · tallest section ${Math.max(...blocks)} floors. Changes are a draft until applied.`:'Empty footprint. Paint at least one square before applying or exporting.';}
 function remember(){history.push(snapshot());if(history.length>20)history.shift();}
 function replace(blocks,save=true,materials=get().materials){if(save)remember();const next={...get(),blocks};if(materials)next.materials=[...materials];else delete next.materials;set(next);memory=snapshot();refresh();}
 function brush(){const n=Number($('blockBrush').value);if($('blockBrush').value.trim()===''||!Number.isInteger(n)||n<0||n>24){$('blockStatus').textContent='Choose a whole height from 0 to 24.';return null;}return n;}
 function paint(index,drag=false){if(!isBlocks())return;const tool=$('blockTool').value;let next,materials=get().materials;if(tool==='height'){const height=brush();if(height===null||get().blocks[index]===height)return;next=paintBuildingBlock(get().blocks,index%10,Math.floor(index/10),height);}else{const side=Number($('blockSide').value);if(!exposedSurface(get().blocks,index,side))return;materials=paintBuildingSurface(get().blocks,materials,index,side,Number($('blockMaterial').value),tool==='fill');if(materials.every((v,i)=>v===(get().materials?.[i]||0)))return;next=[...get().blocks];}if(!drag||!strokeSaved){remember();strokeSaved=true;}replace(next,false,materials);}
 $('blockMode').onchange=()=>{if($('blockMode').value==='blocks'){set({...get(),...(memory?structuredClone(memory):{blocks:towerToBlocks(get())})});}else{memory=get().blocks?snapshot():memory;const next={...get()};delete next.blocks;delete next.materials;set(next);}history.length=0;refresh();};
 $('blockUndo').onclick=()=>{if(history.length){const old=history.pop();replace(old.blocks,false,old.materials||null);}};$('blockClear').onclick=()=>replace(Array(100).fill(0),true,null);$('blockFromTower').onclick=()=>replace(towerToBlocks(get()),true,null);
 for(const id of ['blockTool','blockSide','blockMaterial'])$(id).onchange=refresh;
 grid.onpointerdown=event=>{if(event.button!==0)return;const cell=event.target.closest('[data-block-index]');if(!cell)return;event.preventDefault();stroke=event.pointerId;strokeSaved=false;active=Number(cell.dataset.blockIndex);cell.focus({preventScroll:true});grid.setPointerCapture(event.pointerId);paint(active,true);refresh();};
 grid.onpointermove=event=>{if(stroke!==event.pointerId)return;const cell=document.elementFromPoint(event.clientX,event.clientY)?.closest('[data-block-index]');if(cell&&grid.contains(cell))paint(Number(cell.dataset.blockIndex),true);};
 grid.onpointerup=grid.onpointercancel=()=>{stroke=null;strokeSaved=false;};
 grid.onclick=event=>{if(event.detail!==0)return;const cell=event.target.closest('[data-block-index]');if(cell){active=Number(cell.dataset.blockIndex);paint(active);}};
 grid.onkeydown=event=>{const moves={ArrowLeft:-1,ArrowRight:1,ArrowUp:-10,ArrowDown:10};if(!(event.key in moves))return;event.preventDefault();const cell=event.target.closest('[data-block-index]');if(cell)active=Number(cell.dataset.blockIndex);const next=active+moves[event.key];if(next<0||next>=100||event.key==='ArrowLeft'&&active%10===0||event.key==='ArrowRight'&&active%10===9)return;active=next;refresh();cells[active].focus();};
 return {reset(){history.length=0;memory=get().blocks?snapshot():null;stroke=null;refresh();},refresh};
}
